 export function denyListed(argv: string[], cwd: string): Hit | undefined {
-  throw new Error('not implemented');
+  if (argv.length === 0) return undefined;
+  const cmd = basename(argv[0]);
+  const rest = argv.slice(1);
+
+  if (cmd === 'git') {
+    let i = 1;
+    while (i < argv.length && argv[i].startsWith('-')) i += gitOptsWithValue.has(argv[i]) ? 2 : 1;
+    const sub = argv[i];
+    const args = argv.slice(i + 1);
+    if (sub === 'push' && args.some((w) => forceWords.some((f) => w === f || w.startsWith(f + '=')) || shortGroup(w, 'fd') || w.startsWith('+') || w.startsWith(':')))
+      return { name: 'force-push', reason: 'git push --force rewrites remote history' };
+    if (sub === 'reset' && args.includes('--hard')) return { name: 'reset-hard', reason: 'git reset --hard discards uncommitted changes' };
+    if (sub === 'clean' && (args.includes('--force') || args.some((w) => shortGroup(w, 'f'))) && !args.includes('-n') && !args.includes('--dry-run'))
+      return { name: 'clean-force', reason: 'git clean -f deletes untracked files' };
+    return undefined;
+  }
+
+  if (cmd === 'rm') {
+    const flags: string[] = [];
+    const targets: string[] = [];
+    let endOfOpts = false;
+    for (const w of rest) {
+      if (!endOfOpts && w === '--') endOfOpts = true;
+      else if (!endOfOpts && w.startsWith('-')) flags.push(w);
+      else targets.push(w);
+    }
+    if (!flags.some((w) => w === '--recursive' || shortGroup(w, 'rR'))) return undefined;
+    if (targets.length === 0 || targets.some((t) => unresolvable(t) || !insideWorkspace(t, cwd) || sameDir(t, cwd))) return outside;
+    return undefined;
+  }
+
+  if (cmd === 'find') {
+    if (!rest.some((w) => w === '-delete' || w === '-exec' || w === '-execdir')) return undefined;
+    const end = rest.findIndex((w) => w.startsWith('-'));
+    const starts = end === -1 ? rest : rest.slice(0, end);
+    const paths = starts.length ? starts : ['.'];
+    if (paths.some((p) => unresolvable(p) || !insideWorkspace(p, cwd))) return outside;
+    return undefined;
+  }
+
+  return undefined;
 }

